#!/usr/bin/env python3
"""Supplementary training data for JARVIS Brain 14B.

Adds ~250 records focused on weak categories and more diverse coverage.
"""
import json
from pathlib import Path

SYSTEM = "Bạn là JARVIS — trợ lý AI cá nhân thông minh."
OUTPUT = Path(__file__).parent.parent / "training" / "data" / "processed" / "curated_v3_sft.jsonl"


def rec(user: str, assistant: str, category: str) -> dict:
    return {
        "messages": [
            {"role": "system", "content": SYSTEM},
            {"role": "user", "content": user},
            {"role": "assistant", "content": assistant},
        ],
        "metadata": {"category": category, "curated": True, "version": "v3"},
    }


def math_advanced() -> list[dict]:
    return [
        rec("Tính đạo hàm của f(x) = x^3 + 2x^2 - 5x + 3", "f'(x) = 3x² + 4x - 5\n\n**Áp dụng công thức:**\n- d/dx(x³) = 3x²\n- d/dx(2x²) = 4x\n- d/dx(-5x) = -5\n- d/dx(3) = 0\n\nVậy f'(x) = 3x² + 4x - 5", "math"),
        rec("Giải phương trình bậc 2: x² - 5x + 6 = 0", "Dùng công thức: x = (-b ± √(b²-4ac)) / 2a\n\na=1, b=-5, c=6\nΔ = 25 - 24 = 1\n\nx₁ = (5 + 1) / 2 = 3\nx₂ = (5 - 1) / 2 = 2\n\n**Nghiệm: x = 2 hoặc x = 3**\n\nKiểm tra: 2² - 5(2) + 6 = 0 ✓ | 3² - 5(3) + 6 = 0 ✓", "math"),
        rec("Tính tích phân ∫(2x + 3)dx", "∫(2x + 3)dx = x² + 3x + C\n\n**Giải thích:**\n- ∫2x dx = 2 × (x²/2) = x²\n- ∫3 dx = 3x\n- C là hằng số tích phân\n\nVậy kết quả: **x² + 3x + C**", "math"),
        rec("100 factorial có bao nhiêu chữ số 0 ở cuối?", "Số chữ số 0 cuối = số lần 10 là thừa số = min(số thừa số 2, số thừa số 5)\n\nĐếm thừa số 5 trong 100!:\n- ⌊100/5⌋ = 20\n- ⌊100/25⌋ = 4\n- ⌊100/125⌋ = 0\n\nTổng = 20 + 4 = **24 chữ số 0**\n\n(Thừa số 2 luôn nhiều hơn 5, nên chỉ cần đếm 5)", "math"),
        rec("Fibonacci thứ 10 là bao nhiêu?", "Dãy Fibonacci: mỗi số = tổng 2 số trước\n\n```\nF(1)  = 1\nF(2)  = 1\nF(3)  = 2\nF(4)  = 3\nF(5)  = 5\nF(6)  = 8\nF(7)  = 13\nF(8)  = 21\nF(9)  = 34\nF(10) = 55\n```\n\n**Fibonacci thứ 10 = 55**", "math"),
        rec("Xác suất tung 2 xúc xắc được tổng = 7?", "Tổng trường hợp: 6 × 6 = 36\n\nCác cặp cho tổng = 7:\n- (1,6), (2,5), (3,4), (4,3), (5,2), (6,1)\n→ 6 trường hợp thuận lợi\n\n**P(tổng = 7) = 6/36 = 1/6 ≈ 16.67%**\n\nĐây là tổng có xác suất cao nhất khi tung 2 xúc xắc!", "math"),
        rec("Big O notation: O(n log n) có nghĩa là gì?", "**O(n log n)** — Quasilinear complexity:\n\n- Tăng nhanh hơn linear O(n) nhưng chậm hơn quadratic O(n²)\n- Phổ biến trong: Merge Sort, Quick Sort (average), Heap Sort\n\n**So sánh với n = 1000:**\n- O(n) = 1,000\n- O(n log n) ≈ 10,000\n- O(n²) = 1,000,000\n\n**Ứng dụng:** Hầu hết thuật toán sort tối ưu đều O(n log n)", "math"),
        rec("Tính diện tích tam giác có 3 cạnh a=3, b=4, c=5", "Dùng công thức Heron:\n\ns = (a+b+c)/2 = (3+4+5)/2 = 6\n\nS = √(s(s-a)(s-b)(s-c))\nS = √(6 × 3 × 2 × 1)\nS = √36 = **6**\n\n(Đây là tam giác vuông 3-4-5, nên cũng có thể tính: S = (3×4)/2 = 6)", "math"),
        rec("Logarithm: log₂(256) = ?", "log₂(256) = ?\n\nTìm x sao cho 2^x = 256:\n- 2¹ = 2\n- 2² = 4\n- 2⁴ = 16\n- 2⁸ = 256\n\n**log₂(256) = 8**\n\n(256 = 2⁸, nên log base 2 = 8)", "math"),
        rec("Ma trận 2x2: tính determinant [[3,7],[1,5]]", "det(A) = ad - bc\n\nA = |3  7|\n    |1  5|\n\ndet = (3)(5) - (7)(1) = 15 - 7 = **8**\n\nVì det ≠ 0, ma trận này khả nghịch (invertible).", "math"),
    ]


def analysis() -> list[dict]:
    return [
        rec("So sánh Python và JavaScript", "**Python vs JavaScript:**\n\n| Tiêu chí | Python | JavaScript |\n|---|---|---|\n| Cú pháp | Rõ ràng, indent-based | C-style, linh hoạt |\n| Typing | Dynamic (có type hints) | Dynamic (có TypeScript) |\n| Backend | Django, FastAPI, Flask | Node.js, Express, Nest |\n| Frontend | Không phổ biến | Dominant (React, Vue) |\n| ML/AI | Dominant (PyTorch, TF) | Đang phát triển |\n| Speed | Chậm hơn (interpreted) | Nhanh hơn (V8 engine) |\n| Package | pip (PyPI) | npm (largest registry) |\n\n**Chọn Python nếu:** ML/AI, data science, scripting, backend\n**Chọn JS nếu:** Full-stack web, frontend, real-time apps", "analysis"),
        rec("Phân tích ưu nhược điểm của microservices", "**Microservices Architecture:**\n\n**Ưu điểm:**\n- Scale độc lập từng service\n- Team tự chủ, deploy riêng\n- Fault isolation (1 service crash không ảnh hưởng hệ thống)\n- Tech flexibility (service A dùng Python, B dùng Go)\n\n**Nhược điểm:**\n- Complexity tăng (network latency, distributed tracing)\n- Data consistency khó (eventual consistency)\n- DevOps overhead (monitoring, logging, deployment)\n- Debugging phức tạp hơn monolith\n\n**Khi nào dùng:**\n- Team > 10 devs, nhiều domain khác nhau\n- Cần scale từng phần riêng\n- Chấp nhận complexity overhead\n\n**Khi nào KHÔNG dùng:**\n- MVP, startup nhỏ, team < 5", "analysis"),
        rec("So sánh SQL vs NoSQL", "**SQL vs NoSQL:**\n\n| | SQL | NoSQL |\n|---|---|---|\n| Schema | Fixed (table, rows) | Flexible (document, key-value) |\n| Scaling | Vertical (scale up) | Horizontal (scale out) |\n| ACID | Có (strong consistency) | Hạn chế (eventual consistency) |\n| Joins | Native | Không hoặc hạn chế |\n| Ví dụ | PostgreSQL, MySQL | MongoDB, Redis, Cassandra |\n\n**Chọn SQL:** Financial data, complex queries, relationships\n**Chọn NoSQL:** Big data, flexible schema, real-time, caching", "analysis"),
        rec("Phân tích trend AI 2025-2026", "**AI Trends 2025-2026:**\n\n1. **Small Language Models (SLMs)**: Qwen3, Phi-4, Gemma — chạy local trên consumer hardware\n2. **Agentic AI**: Agents tự thực hiện task phức tạp (coding, research, planning)\n3. **Multimodal AI**: Text + Image + Audio + Video trong 1 model\n4. **RAG maturity**: Better retrieval, hybrid search, knowledge graphs\n5. **AI Coding Assistants**: GitHub Copilot, Claude Code, Cursor — thay đổi workflow dev\n6. **Open-source dominance**: Qwen, Llama, Mistral cạnh tranh closed models\n7. **Edge AI**: Inference trên mobile/IoT devices\n8. **AI Safety**: Alignment, red teaming, governance frameworks\n\nXu hướng chung: AI ngày càng nhỏ hơn, mạnh hơn, chạy local được.", "analysis"),
        rec("Review code này: for i in range(len(lst)): total += lst[i]", "**Code Review:**\n\n```python\n# ❌ Anti-pattern: indexing trong loop\nfor i in range(len(lst)):\n    total += lst[i]\n\n# ✅ Pythonic: iterate trực tiếp\ntotal = sum(lst)\n\n# Hoặc nếu cần logic phức tạp:\nfor item in lst:\n    total += item\n```\n\n**Vấn đề:**\n1. `range(len())` là anti-pattern trong Python\n2. Indexing `lst[i]` chậm hơn direct iteration\n3. Có built-in `sum()` cho task này\n\n**Tổng kết:** Dùng `sum(lst)` — ngắn gọn, nhanh, Pythonic.", "analysis"),
        rec("Giải thích CAP theorem", "**CAP Theorem** — chỉ chọn được 2/3:\n\n- **C**onsistency: Mọi read nhận được write mới nhất\n- **A**vailability: Mọi request nhận response (không lỗi)\n- **P**artition tolerance: Hệ thống hoạt động dù network split\n\n**Thực tế:** Partition luôn xảy ra → chọn CP hoặc AP:\n\n| Hệ thống | Loại | Ví dụ |\n|---|---|---|\n| CP | Consistency > Availability | PostgreSQL, MongoDB (default) |\n| AP | Availability > Consistency | Cassandra, DynamoDB, CouchDB |\n\n**Tip:** Hầu hết ứng dụng cần eventual consistency (AP) là đủ.", "analysis"),
        rec("Đánh giá FastAPI vs Django", "**FastAPI vs Django:**\n\n| | FastAPI | Django |\n|---|---|---|\n| Type | Modern async framework | Full-stack framework |\n| Speed | Rất nhanh (async/await) | Trung bình |\n| Admin | Không có | Built-in admin panel |\n| ORM | Không (dùng SQLAlchemy) | Django ORM built-in |\n| Auth | Tự implement | Built-in |\n| API docs | Auto (Swagger/ReDoc) | DRF add-on |\n| Learning | Dễ | Trung bình |\n\n**Chọn FastAPI:** API-only, microservices, performance-critical\n**Chọn Django:** Full-stack web, CMS, rapid prototyping, admin-heavy apps", "analysis"),
        rec("SOLID principles là gì?", "**SOLID** — 5 nguyên tắc OOP:\n\n**S** — Single Responsibility: 1 class = 1 nhiệm vụ\n**O** — Open/Closed: Mở để extend, đóng để modify\n**L** — Liskov Substitution: Subclass thay thế được parent\n**I** — Interface Segregation: Interface nhỏ, specific\n**D** — Dependency Inversion: Depend on abstractions, not concretions\n\n**Ví dụ DI:**\n```python\n# ❌ Tight coupling\nclass OrderService:\n    def __init__(self):\n        self.db = PostgresDB()  # Concrete\n\n# ✅ Dependency Inversion\nclass OrderService:\n    def __init__(self, db: Database):  # Abstract\n        self.db = db\n```", "analysis"),
    ]


