def security_expanded() -> list[dict]:
    return [
        rec("SQL injection là gì và cách phòng chống?", "**SQL Injection** — chèn code SQL vào input:\n\n```\n# Vulnerable\nquery = f\"SELECT * FROM users WHERE name = '{user_input}'\"\n# Input: ' OR '1'='1\n# → SELECT * FROM users WHERE name = '' OR '1'='1'\n```\n\n**Phòng chống:**\n```python\n# ✅ Parameterized queries\ncursor.execute(\"SELECT * FROM users WHERE name = ?\", (user_input,))\n\n# ✅ ORM (SQLAlchemy)\nUser.query.filter_by(name=user_input).first()\n\n# ✅ Input validation\nimport re\nif not re.match(r'^[a-zA-Z0-9]+$', user_input):\n    raise ValueError(\"Invalid input\")\n```\n\n**Rule:** KHÔNG BAO GIỜ dùng f-string hoặc string concat cho SQL queries!", "security"),
        rec("XSS attack là gì?", "**XSS** (Cross-Site Scripting) — chèn JavaScript vào web page:\n\n**Loại:**\n1. **Stored XSS**: Script lưu trong DB, execute khi load page\n2. **Reflected XSS**: Script trong URL, execute khi click link\n3. **DOM XSS**: Client-side JS processing untrusted data\n\n**Ví dụ:**\n```html\n<!-- Vulnerable -->\n<p>Hello, {user_name}</p>\n<!-- Input: <script>alert('XSS')</script> -->\n```\n\n**Phòng chống:**\n- Escape HTML output (`&lt;` thay `<`)\n- Content Security Policy (CSP) headers\n- HttpOnly cookies (JS không đọc được)\n- Input sanitization\n- Dùng framework (React, Vue tự escape)", "security"),
        rec("HTTPS hoạt động thế nào?", "**HTTPS** = HTTP + TLS encryption:\n\n**TLS Handshake:**\n1. Client gửi \"Hello\" + supported ciphers\n2. Server chọn cipher + gửi certificate\n3. Client verify certificate (CA chain)\n4. Key exchange (Diffie-Hellman)\n5. Both sides derive session key\n6. Encrypted communication begins\n\n**Đảm bảo:**\n- **Confidentiality**: Data encrypted (AES-256)\n- **Integrity**: MAC verify data không bị sửa\n- **Authentication**: Certificate verify server identity\n\n**Setup:**\n```bash\n# Free SSL with Let's Encrypt\nsudo certbot --nginx -d mysite.com\n```", "security"),
        rec("JWT token hoạt động thế nào?", "**JWT** (JSON Web Token) — stateless authentication:\n\n**Cấu trúc:** `header.payload.signature`\n\n```\n# Header (base64)\n{\"alg\": \"HS256\", \"typ\": \"JWT\"}\n\n# Payload (base64)\n{\"sub\": \"user123\", \"exp\": 1709753600, \"role\": \"admin\"}\n\n# Signature\nHMAC-SHA256(header + \".\" + payload, secret_key)\n```\n\n**Flow:**\n1. User login → Server tạo JWT\n2. Client lưu JWT (localStorage/cookie)\n3. Mỗi request gửi: `Authorization: Bearer <token>`\n4. Server verify signature, check expiry\n\n**Best practices:**\n- Short expiry (15-30 min)\n- Refresh tokens for long sessions\n- KHÔNG lưu sensitive data trong payload", "security"),
    ]


def build_all() -> list[dict]:
    all_data = []
    generators = [
        math_advanced, analysis, factual_expanded, coding_patterns,
        devops_expanded, conversation_extended, security_expanded,
    ]
    for gen in generators:
        records = gen()
        all_data.extend(records)
        print(f"  {gen.__name__}: {len(records)} records")
    return all_data


def main():
    print("Building supplementary training data v3...")
    records = build_all()

    from collections import Counter
    cats = Counter(r["metadata"]["category"] for r in records)
    print(f"\nTotal: {len(records)} records across {len(cats)} categories")
    for cat, count in sorted(cats.items()):
        print(f"  {cat}: {count}")

    OUTPUT.parent.mkdir(parents=True, exist_ok=True)
    with open(OUTPUT, "w", encoding="utf-8") as f:
        for r in records:
            f.write(json.dumps(r, ensure_ascii=False) + "\n")
    print(f"\nSaved to {OUTPUT}")


if __name__ == "__main__":
    main()
